public class JwtBuilder {

    private final Map<String, Object> claims = new LinkedHashMap<>();
    private Key key;
    private SignatureAlgorithm algorithm;

    public JwtBuilder setSubject(String subject) {
        claims.put("sub", subject);
        return this;
    }

    public JwtBuilder claim(String name, Object value) {
        claims.put(name, value);
        return this;
    }

    public JwtBuilder setIssuedAt(Date date) {
        claims.put("iat", date.getTime() / 1000L);
        return this;
    }

    public JwtBuilder setExpiration(Date date) {
        claims.put("exp", date.getTime() / 1000L);
        return this;
    }

    public JwtBuilder signWith(Key key, SignatureAlgorithm algorithm) {
        if (key == null || algorithm == null) {
            throw new IllegalArgumentException("Key and signature algorithm must not be null");
        }
        this.key = key;
        this.algorithm = algorithm;
        return this;
    }

    public String compact() {
        if (key == null || algorithm == null) {
            throw new IllegalStateException("Token must be signed before compacting");
        }
        String headerJson = "{\"alg\":\"" + algorithm.name() + "\"}";
        String header = base64Url(headerJson.getBytes(StandardCharsets.UTF_8));
        StringBuilder payloadJson = new StringBuilder("{");
        boolean first = true;
        for (Map.Entry<String, Object> entry : claims.entrySet()) {
            if (!first) {
                payloadJson.append(',');
            }
            first = false;
            payloadJson.append('"').append(entry.getKey()).append("\":");
            Object value = entry.getValue();
            if (value instanceof Number) {
                payloadJson.append(value);
            } else {
                payloadJson.append('"').append(String.valueOf(value)
                        .replace("\\", "\\\\").replace("\"", "\\\"")).append('"');
            }
        }
        payloadJson.append('}');
        String payload = base64Url(payloadJson.toString().getBytes(StandardCharsets.UTF_8));
        String signingInput = header + "." + payload;
        byte[] signature = hmac(signingInput, key, algorithm);
        return signingInput + "." + base64Url(signature);
    }

    static byte[] hmac(String signingInput, Key key, SignatureAlgorithm algorithm) {
        try {
            String jcaName;
            switch (algorithm) {
                case HS256: jcaName = "HmacSHA256"; break;
                case HS384: jcaName = "HmacSHA384"; break;
                case HS512: jcaName = "HmacSHA512"; break;
                default: throw new IllegalArgumentException("Unsupported algorithm: " + algorithm);
            }
            Mac mac = Mac.getInstance(jcaName);
            mac.init(key);
            return mac.doFinal(signingInput.getBytes(StandardCharsets.US_ASCII));
        } catch (Exception e) {
            throw new io.jsonwebtoken.security.SignatureException("Unable to compute HMAC: " + e.getMessage(), e);
        }
    }

    static byte[] keyBytes(Key key) {
        return key.getEncoded();
    }

    static SecretKey asSecretKey(Key key) {
        return Keys.asSecretKey(key);
    }

